const { accessSync, constants } = await import('node:fs');
const inputPath = process.env.INPUT_PATH;
const outputPath = process.env.OUTPUT_PATH;
if (!inputPath) { throw new Error('Missing INPUT_PATH env var'); }
if (!outputPath) { throw new Error('Missing OUTPUT_PATH env var'); }
try { accessSync(inputPath, constants.R_OK); } catch (e) { throw new Error(`Cannot read input file at ${inputPath}: ${e.message}`); }
globalThis.inputPath = inputPath;
globalThis.outputPath = outputPath;

const fs = await import('node:fs');
const { writeFileSync } = fs;
const jsparsersMod = await import('jsparsers');
const jsp = jsparsersMod.default || jsparsersMod;
const xmlParser = jsp.xml();
// read the XML file (readFile may be sync or async; handle both)
if (typeof xmlParser.readFile === 'function') {
  const maybePromise = xmlParser.readFile(globalThis.inputPath);
  if (maybePromise && typeof maybePromise.then === 'function') { await maybePromise; }
} else {
  throw new Error('xmlParser does not have readFile method');
}
// Convert to TOML – the library exposes a toml() method on the parser object
let tomlStr;
if (typeof xmlParser.toml === 'function') {
  tomlStr = xmlParser.toml();
} else if (typeof xmlParser.toml === 'string') {
  tomlStr = xmlParser.toml;
} else {
  throw new Error('Unable to obtain TOML representation from xml parser');
}
writeFileSync(globalThis.outputPath, tomlStr, 'utf8');
globalThis.toml = tomlStr;
